/**
 * Skills validate command, validate a skill directory
 *
 * @module cli/commands/skills/validate
 */
import { createSuccessEnvelope, isJsonMode, outputJson } from "../../shared/json-output.js";
import { exitProcess, logError, logSuccess, logWarning } from "../../utils/index.js";
import { createFileSystem } from "../../../src/platform/index.js";
import { basename, resolve } from "../../../src/platform/compat/path/index.js";
import { isValidStrictSkillName, parseSkillFrontmatter, validateSkillFileMetadata, } from "../../../src/skill/index.js";
export async function validateSkill(args) {
    const dir = args._[2] ?? ".";
    const issues = await validateSkillDirectory(dir);
    return outputResults(dir, issues);
}
export async function validateSkillDirectory(dir) {
    const issues = [];
    const fs = createFileSystem();
    let content;
    try {
        content = await fs.readTextFile(`${dir}/SKILL.md`);
    }
    catch {
        return [{ severity: "error", message: "SKILL.md not found" }];
    }
    try {
        const parsed = await parseSkillFrontmatter(content);
        const directoryName = basename(resolve(dir));
        validateCanonicalFrontmatterName(parsed.frontmatter, directoryName);
        validateSkillFileMetadata(parsed.frontmatter, directoryName);
        if (!parsed.body.trim()) {
            issues.push({ severity: "warning", message: "SKILL.md body is empty" });
        }
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        issues.push({ severity: "error", message });
    }
    return issues;
}
function validateCanonicalFrontmatterName(frontmatter, directoryName) {
    if (typeof frontmatter.name !== "string")
        return;
    const name = frontmatter.name.trim();
    if (!isValidStrictSkillName(name)) {
        return;
    }
    if (name !== directoryName) {
        throw new Error(`Skill name "${name}" does not match directory name "${directoryName}"`);
    }
}
async function outputResults(dir, issues) {
    const hasErrors = issues.some((i) => i.severity === "error");
    if (isJsonMode()) {
        await outputJson(createSuccessEnvelope("skills", {
            directory: dir,
            valid: !hasErrors,
            issues,
        }));
        if (hasErrors)
            exitProcess(1);
        return;
    }
    if (issues.length === 0) {
        logSuccess(`Skill at "${dir}" is valid`);
        return;
    }
    for (const issue of issues) {
        if (issue.severity === "error") {
            logError(issue.message);
        }
        else {
            logWarning(issue.message);
        }
    }
    if (hasErrors)
        exitProcess(1);
}
